INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7377269, 1157078, 30982, '<td valign="top">Egads - slimy alien eyeballs!  (The harsh lighting here isn''t helping you - more diffuse lighting might make your eyeballs a bit more appealing...)</td>', 'Egads - slimy alien eyeballs!  (The harsh lighting here isn''t helping you - more diffuse lighting might make your eyeballs a bit more appealing...)', '2015-06-30 00:29:17.000000', NULL, 1),
(7377270, 1157636, 30982, '<td valign="top">Eye-tattoo sticks - poke these in your eye to create pleasing natural and permanent bokeh shapes....</td>', 'Eye-tattoo sticks - poke these in your eye to create pleasing natural and permanent bokeh shapes....', '2015-06-30 00:29:56.000000', NULL, 1),
(7377271, 1156910, 30982, '<td valign="top">That would be an anchor-shaped wee bit floating in space, captured with one REALLY freakin'' long lens.  No?  (To be honest, kinda dull picture, but made for a good story...)</td>', 'That would be an anchor-shaped wee bit floating in space, captured with one REALLY freakin'' long lens.  No?  (To be honest, kinda dull picture, but made for a good story...)', '2015-06-30 00:31:06.000000', NULL, 1),
(7377272, 1157772, 30982, '<td valign="top">After several rotations, the alien pod was ready to receive the incoming ship....  (Pretty cool shot of the innards of a plumbing fixture of some kind?)</td>', 'After several rotations, the alien pod was ready to receive the incoming ship....  (Pretty cool shot of the innards of a plumbing fixture of some kind?)', '2015-06-30 00:31:57.000000', NULL, 1),
(7377273, 1157797, 30982, '<td valign="top">The two creatures butted heads, as was the ceremonial greeting of their kind, then awaited the Lapping by the Giant Tongue that would complete the initiation.  (Flower innards?  The white bit is kind of off-putting - indeed looks like a tongue...)</td>', 'The two creatures butted heads, as was the ceremonial greeting of their kind, then awaited the Lapping by the Giant Tongue that would complete the initiation.  (Flower innards?  The white bit is kind of off-putting - indeed looks like a tongue...)', '2015-06-30 00:33:43.000000', NULL, 1),
