INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7382871, 1157634, 46918, '<td valign="top">Hello from the critique club...<br/> <br/>Nice capture. I like the multiple colors that you were able to capture here. I also like the texture of the rock. The only thing I see that I would have wanted different is the dark area towards the bottom of the shot. I know it is just how the light was hitting it but it almost begs to have some color in that area. Happy shooting</td>', 'Hello from the critique club... Nice capture. I like the multiple colors that you were able to capture here. I also like the texture of the rock. The only thing I see that I would have wanted different is the dark area towards the bottom of the shot. I know it is just how the light was hitting it but it almost begs to have some color in that area. Happy shooting', '2015-07-06 12:22:48.000000', NULL, 0),
(7382880, 1156248, 98339, '<td valign="top">Excellent...I wondered if this was yours...I did get some Ferofluid have played a little bit not much.  Good to know that you stack.  That explains a lot for me...excellent as always.</td>', 'Excellent...I wondered if this was yours...I did get some Ferofluid have played a little bit not much.  Good to know that you stack.  That explains a lot for me...excellent as always.', '2015-07-06 12:35:38.000000', NULL, 0),
(7382884, 1157744, 98339, '<td valign="top">try putting either bright fabric or scrap paper (craft printed paper) under the glass...the colors get real interesting.  Excellent</td>', 'try putting either bright fabric or scrap paper (craft printed paper) under the glass...the colors get real interesting.  Excellent', '2015-07-06 12:39:13.000000', NULL, 0),
(7382885, 1157134, 76335, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Melethia:</b></div><hr/><i> So.  A strong 6+ (anything above a 6 seems a bit of a miracle to me these days) AND multiple bits of bling.... what do you have to say for yourself?  Hmmm? </i></td></tr></table> <br/>Indeed, something''s not quite right in the universe. If it''s any consolation, I''m high threes in Rule of Thirds...</td>', 'Originally posted by Melethia: So.  A strong 6+ (anything above a 6 seems a bit of a miracle to me these days) AND multiple bits of bling.... what do you have to say for yourself?  Hmmm?  Indeed, something''s not quite right in the universe. If it''s any consolation, I''m high threes in Rule of Thirds...', '2015-07-06 12:39:59.000000', NULL, 0),
