(7383028, 1156910, 1031, '<td valign="top">Here it is in context: <a href="//www.dpchallenge.com/image.php?IMAGE_ID=1159229" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/0-4999/1031/120/Copyrighted_Image_Reuse_Prohibited_1159229.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/0-4999/1031/120/Copyrighted_Image_Reuse_Prohibited_1159229.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/0-4999/1031/120/Copyrighted_Image_Reuse_Prohibited_1159229.jpg"/></a></td>', 'Here it is in context: ', '2015-07-06 17:57:55.000000', NULL, 0),
(7383047, 1158054, 1031, '<td valign="top">Great shot, though it''s kind of big and complex to be a virus. Now if you''d "stained" it purple it would look a lot like a colony of Gram-positive cocci, such as <a href="https://en.wikipedia.org/wiki/Staphylococcus" rel="nofollow" target="_blank"><i>Staphylococcus</i></a> aureus, which tends to look (microscopically) like "a cluster of grapes".</td>', 'Great shot, though it''s kind of big and complex to be a virus. Now if you''d "stained" it purple it would look a lot like a colony of Gram-positive cocci, such as Staphylococcus aureus, which tends to look (microscopically) like "a cluster of grapes".', '2015-07-06 18:39:30.000000', NULL, 0),
